class Solution:
    def countGoodStrings(self, n: int) -> int:
        mod = 10**9 + 7
        def fib_pair(x):
            if x == 0: return (0, 1)
            a, b = fib_pair(x // 2); c = a * (2 * b - a) % mod; d = (a * a + b * b) % mod
            return (d, (c + d) % mod) if x & 1 else (c, d)
        return 2 * fib_pair(n)[0] % mod
